/* Kernel implementation in Exo:
 *
 * This Exo code defines a straightforward, mathematically equivalent
 * MVT kernel and then applies a performance schedule:
 *  - Use scalar temporaries to keep x1[i] / x2[i] in registers.
 *  - Tile the outer i-loop of each MVT and parallelize over tiles.
 *  - Tile and fully unroll the inner j-loop with a small unroll factor.
 * The final public procedure is named `kernel_mvt` and matches the
 * signature expected by the C driver.
 */
 /*
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# NOTE: DATA_TYPE is a placeholder that will be substituted by the
# build system with the actual scalar type (e.g., f32 or f64).

@proc
def kernel_mvt(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # The PolyBench MVT kernel:
    #   x1[i] += sum_j A[i,j] * y_1[j]
    #   x2[i] += sum_j A[j,i] * y_2[j]
    # We keep the two GEMV-like operations separate so each can be
    # scheduled independently and parallelized along its outer loop.
    assert n > 0

    # First matrix-vector multiply: x1 += A * y_1
    for i in seq(0, n):
        # Keep the current x1[i] in a scalar accumulator to reduce
        # redundant loads and stores to memory.
        acc1: DATA_TYPE
        acc1 = x1[i]
        for j in seq(0, n):
            acc1 += A[i, j] * y_1[j]
        x1[i] = acc1

    # Second matrix-vector multiply with A^T: x2 += A^T * y_2
    for i in seq(0, n):
        # Same idea: accumulate x2[i] in a scalar.
        acc2: DATA_TYPE
        acc2 = x2[i]
        for j in seq(0, n):
            acc2 += A[j, i] * y_2[j]
        x2[i] = acc2


# ---------------------------------------------------------------------------
# Performance schedule
# ---------------------------------------------------------------------------

# Work on a copy so that the original mathematical spec remains available.
kernel_mvt_opt = rename(kernel_mvt, "kernel_mvt_opt")

# Tunable constants:
# - T_I: tile size along the outer i dimension (rows of A).
# - VEC_J: small unroll factor for the inner j dimension.
T_I  = 64   # good default for modern x86 cache hierarchies
VEC_J = 4   # unroll factor for the inner j loop

# ---------------------------
# Optimize the first MVT (x1)
# ---------------------------

# 1. Tile the outer i loop of the first MVT: i -> (io1, ii1).
#    Each io1-iteration handles a block of rows, which we later
#    parallelize across cores.
i1 = kernel_mvt_opt.find_loop("i")
kernel_mvt_opt = divide_loop(kernel_mvt_opt, i1, T_I, ["io1", "ii1"], tail="guard")

# 2. Tile and unroll the inner j loop of the first MVT: j -> (jo1, ji1).
#    ji1 has a constant bound VEC_J, which we fully unroll to improve
#    instruction-level parallelism and enable vectorization.
j1 = kernel_mvt_opt.find_loop("j")
kernel_mvt_opt = divide_loop(kernel_mvt_opt, j1, VEC_J, ["jo1", "ji1"], tail="guard")
ji1 = kernel_mvt_opt.find_loop("ji1")
kernel_mvt_opt = unroll_loop(kernel_mvt_opt, ji1)

# 3. Parallelize the tiled outer loop over io1 (blocks of rows of A).
#    Each tile writes a disjoint subset of x1, so this is safe.
io1 = kernel_mvt_opt.find_loop("io1")
kernel_mvt_opt = parallelize_loop(kernel_mvt_opt, io1)

# ---------------------------
# Optimize the second MVT (x2)
# ---------------------------

# At this point, the only remaining loop named "i" is the outer loop
# of the second MVT, so we can tile and parallelize it similarly.

# 4. Tile the outer i loop of the second MVT: i -> (io2, ii2).
i2 = kernel_mvt_opt.find_loop("i")
kernel_mvt_opt = divide_loop(kernel_mvt_opt, i2, T_I, ["io2", "ii2"], tail="guard")

# 5. Tile and unroll the inner j loop of the second MVT: j -> (jo2, ji2).
j2 = kernel_mvt_opt.find_loop("j")
kernel_mvt_opt = divide_loop(kernel_mvt_opt, j2, VEC_J, ["jo2", "ji2"], tail="guard")
ji2 = kernel_mvt_opt.find_loop("ji2")
kernel_mvt_opt = unroll_loop(kernel_mvt_opt, ji2)

# 6. Parallelize over tiles of rows for the second MVT as well.
#    As with the first kernel, each io2-iteration updates a disjoint
#    range of x2 indices.
io2 = kernel_mvt_opt.find_loop("io2")
kernel_mvt_opt = parallelize_loop(kernel_mvt_opt, io2)

# 7. Clean up the IR: constant folding, dead-code elimination, etc.
kernel_mvt_opt = simplify(kernel_mvt_opt)

# 8. Expose the optimized procedure under the original public name.
kernel_mvt = rename(kernel_mvt_opt, "kernel_mvt")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A,   DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to 1D pointers. */
  kernel_mvt(/*ctxt=*/NULL, n,
             (DATA_TYPE*)POLYBENCH_ARRAY(x1),
             (DATA_TYPE*)POLYBENCH_ARRAY(x2),
             (DATA_TYPE*)POLYBENCH_ARRAY(y_1),
             (DATA_TYPE*)POLYBENCH_ARRAY(y_2),
             (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n,
                                    POLYBENCH_ARRAY(x1),
                                    POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
}
