    # First matrix-vector product:
    #   x1[i] += sum_j A[i,j] * y_1[j]
    # We accumulate into a scalar tmp1 to keep x1[i] in a register.
    for i in seq(0, n):
        tmp1: DATA_TYPE
        tmp1 = x1[i]
        for j in seq(0, n):
            tmp1 += A[i, j] * y_1[j]
        x1[i] = tmp1

    # Second matrix-vector product rewritten to access A row-major.
    # Original PolyBench code:
    #   for i in 0..n-1:
    #     for j in 0..n-1:
    #       x2[i] += A[j, i] * y_2[j]
    #
    # This is algebraically equivalent to:
    #   for j in 0..n-1:
    #     t2 = y_2[j]
    #     for i in 0..n-1:
    #       x2[i] += A[j, i] * t2
    #
    # The latter form reads rows of A contiguously, improving spatial locality.
    for j in seq(0, n):
        t2: DATA_TYPE
        t2 = y_2[j]
        for i in seq(0, n):
            x2[i] += A[j, i] * t2

